insert into questions (difficulty,type,prompt,prompt_en,code,language,options,options_en,correct_index,explanation,explanation_en,hint,hint_en,hint2,hint2_en,hint3,hint3_en) values
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] --proxy-port 8080 --intercept on','bash','["Burp Suite","SQLmap","Nikto","Nmap"]'::jsonb,'["Burp Suite","SQLmap","Nikto","Nmap"]'::jsonb,0,'Burp Suite (Intercepting Proxy): Menangkap dan memanipulasi request/response HTTP antara browser dan server sebelum terkirim.','Burp Suite (Intercepting Proxy): Intercepts and manipulates HTTP requests/responses between browser and server before they''re sent.','Tools ini bernama Burp Suite, fungsinya: Menangkap dan memanipulasi request/response HTTP antara browser dan server sebelum terkirim.','This tool is called Burp Suite, and it: Intercepts and manipulates HTTP requests/responses between browser and server before they''re sent.','Arahkan proxy browser ke 127.0.0.1:8080, buka tab Proxy → Intercept, lalu ubah nilai parameter yang lewat.','Point your browser''s proxy to 127.0.0.1:8080, open Proxy → Intercept, then edit the parameter values passing through.','Di dunia nyata, celah ini dicegah dengan validasi di sisi SERVER, bukan cuma mengandalkan JavaScript di browser.','In the real world this is prevented with SERVER-SIDE validation, not just trusting browser-side JavaScript.'),
('demi_god','fill','Lengkapi perintah Burp Suite berikut:','Complete the following Burp Suite command:','burpsuite --proxy-port 8080 ____','bash','["--scan full","--headless true","--export pdf","--intercept on"]'::jsonb,'["--scan full","--headless true","--export pdf","--intercept on"]'::jsonb,3,'Bagian yang hilang adalah "--intercept on". Arahkan proxy browser ke 127.0.0.1:8080, buka tab Proxy → Intercept, lalu ubah nilai parameter yang lewat.','The missing part is "--intercept on". Point your browser''s proxy to 127.0.0.1:8080, open Proxy → Intercept, then edit the parameter values passing through.','Burp Suite dipakai untuk: Menangkap dan memanipulasi request/response HTTP antara browser dan server sebelum terkirim.','Burp Suite is used to: Intercepts and manipulates HTTP requests/responses between browser and server before they''re sent.','Arahkan proxy browser ke 127.0.0.1:8080, buka tab Proxy → Intercept, lalu ubah nilai parameter yang lewat.','Point your browser''s proxy to 127.0.0.1:8080, open Proxy → Intercept, then edit the parameter values passing through.','Di dunia nyata, celah ini dicegah dengan validasi di sisi SERVER, bukan cuma mengandalkan JavaScript di browser.','In the real world this is prevented with SERVER-SIDE validation, not just trusting browser-side JavaScript.'),
('demi_god','guess','Apa fungsi dari Burp Suite?','What is Burp Suite used for?','// Burp Suite — Intercepting Proxy','bash','["Memindai situs WordPress untuk plugin, tema, dan versi core yang punya celah diketahui.","Mencoba banyak kombinasi username/password untuk membobol halaman login.","Menangkap dan memanipulasi request/response HTTP antara browser dan server sebelum terkirim.","Mengirim request HTTP langsung dari terminal untuk menguji API atau endpoint secara manual."]'::jsonb,'["Scans a WordPress site for plugins, themes, and core versions with known vulnerabilities.","Tries many username/password combinations to break into a login page.","Intercepts and manipulates HTTP requests/responses between browser and server before they''re sent.","Sends HTTP requests directly from the terminal to manually test an API or endpoint."]'::jsonb,2,'Burp Suite: Menangkap dan memanipulasi request/response HTTP antara browser dan server sebelum terkirim.','Burp Suite: Intercepts and manipulates HTTP requests/responses between browser and server before they''re sent.','Burp Suite adalah kategori "Intercepting Proxy".','Burp Suite falls under the "Intercepting Proxy" category.','Arahkan proxy browser ke 127.0.0.1:8080, buka tab Proxy → Intercept, lalu ubah nilai parameter yang lewat.','Point your browser''s proxy to 127.0.0.1:8080, open Proxy → Intercept, then edit the parameter values passing through.','Di dunia nyata, celah ini dicegah dengan validasi di sisi SERVER, bukan cuma mengandalkan JavaScript di browser.','In the real world this is prevented with SERVER-SIDE validation, not just trusting browser-side JavaScript.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] quick-scan --self-contained -o /[TOOL]/wrk/report.html https://target.id','bash','["Postman","OWASP ZAP","WPScan","Wireshark"]'::jsonb,'["Postman","OWASP ZAP","WPScan","Wireshark"]'::jsonb,1,'OWASP ZAP (Web Vulnerability Scanner): Pemindai otomatis celah keamanan aplikasi web open-source dari OWASP.','OWASP ZAP (Web Vulnerability Scanner): OWASP''s open-source automated web application vulnerability scanner.','Tools ini bernama OWASP ZAP, fungsinya: Pemindai otomatis celah keamanan aplikasi web open-source dari OWASP.','This tool is called OWASP ZAP, and it: OWASP''s open-source automated web application vulnerability scanner.','Masukkan URL target di kolom ''Automated Scan'', klik Attack, lalu baca laporan Alerts.','Enter the target URL in ''Automated Scan'', click Attack, then read the Alerts report.','Scan otomatis cuma menangkap pola yang sudah dikenal; selalu verifikasi manual sebelum melapor sebagai celah nyata.','Automated scans only catch known patterns; always verify manually before reporting a real finding.'),
('demi_god','fill','Lengkapi perintah OWASP ZAP berikut:','Complete the following OWASP ZAP command:','zap-cli ____ --self-contained -o /zap/wrk/report.html https://target.id','bash','["quick-scan","sql-dump","brute-force","port-scan"]'::jsonb,'["quick-scan","sql-dump","brute-force","port-scan"]'::jsonb,0,'Bagian yang hilang adalah "quick-scan". Masukkan URL target di kolom ''Automated Scan'', klik Attack, lalu baca laporan Alerts.','The missing part is "quick-scan". Enter the target URL in ''Automated Scan'', click Attack, then read the Alerts report.','OWASP ZAP dipakai untuk: Pemindai otomatis celah keamanan aplikasi web open-source dari OWASP.','OWASP ZAP is used to: OWASP''s open-source automated web application vulnerability scanner.','Masukkan URL target di kolom ''Automated Scan'', klik Attack, lalu baca laporan Alerts.','Enter the target URL in ''Automated Scan'', click Attack, then read the Alerts report.','Scan otomatis cuma menangkap pola yang sudah dikenal; selalu verifikasi manual sebelum melapor sebagai celah nyata.','Automated scans only catch known patterns; always verify manually before reporting a real finding.'),
('demi_god','guess','Apa fungsi dari OWASP ZAP?','What is OWASP ZAP used for?','// OWASP ZAP — Web Vulnerability Scanner','bash','["Pemindai otomatis celah keamanan aplikasi web open-source dari OWASP.","Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.","Memeriksa dan mengubah HTML/CSS/JS serta request jaringan langsung dari browser.","Alternatif curl yang lebih mudah dibaca untuk menguji request/response HTTP dari terminal."]'::jsonb,'["OWASP''s open-source automated web application vulnerability scanner.","Captures and inspects network packets in fine detail.","Inspects and edits HTML/CSS/JS and network requests right from the browser.","A more readable curl alternative for testing HTTP requests/responses from the terminal."]'::jsonb,0,'OWASP ZAP: Pemindai otomatis celah keamanan aplikasi web open-source dari OWASP.','OWASP ZAP: OWASP''s open-source automated web application vulnerability scanner.','OWASP ZAP adalah kategori "Web Vulnerability Scanner".','OWASP ZAP falls under the "Web Vulnerability Scanner" category.','Masukkan URL target di kolom ''Automated Scan'', klik Attack, lalu baca laporan Alerts.','Enter the target URL in ''Automated Scan'', click Attack, then read the Alerts report.','Scan otomatis cuma menangkap pola yang sudah dikenal; selalu verifikasi manual sebelum melapor sebagai celah nyata.','Automated scans only catch known patterns; always verify manually before reporting a real finding.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] -sV -p- 192.168.1.10','bash','["Gobuster","Nmap","WPScan","Chrome DevTools"]'::jsonb,'["Gobuster","Nmap","WPScan","Chrome DevTools"]'::jsonb,1,'Nmap (Network Scanner): Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya.','Nmap (Network Scanner): Scans hosts and open ports on a network, including service versions.','Tools ini bernama Nmap, fungsinya: Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya.','This tool is called Nmap, and it: Scans hosts and open ports on a network, including service versions.','Jalankan di terminal diarahkan ke IP/domain target; hasilnya daftar port terbuka dan servis yang berjalan.','Run it in a terminal pointed at the target IP/domain; the output lists open ports and running services.','Admin server yang baik menutup port yang tidak dipakai (least privilege) alih-alih mengandalkan ''tidak ketahuan''.','A good admin closes unused ports (least privilege) instead of relying on ''security through obscurity''.'),
('demi_god','fill','Lengkapi perintah Nmap berikut:','Complete the following Nmap command:','nmap ____ -p- 192.168.1.10','bash','["-sV","-sS","-O","-A"]'::jsonb,'["-sV","-sS","-O","-A"]'::jsonb,0,'Bagian yang hilang adalah "-sV". Jalankan di terminal diarahkan ke IP/domain target; hasilnya daftar port terbuka dan servis yang berjalan.','The missing part is "-sV". Run it in a terminal pointed at the target IP/domain; the output lists open ports and running services.','Nmap dipakai untuk: Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya.','Nmap is used to: Scans hosts and open ports on a network, including service versions.','Jalankan di terminal diarahkan ke IP/domain target; hasilnya daftar port terbuka dan servis yang berjalan.','Run it in a terminal pointed at the target IP/domain; the output lists open ports and running services.','Admin server yang baik menutup port yang tidak dipakai (least privilege) alih-alih mengandalkan ''tidak ketahuan''.','A good admin closes unused ports (least privilege) instead of relying on ''security through obscurity''.'),
('demi_god','guess','Apa fungsi dari Nmap?','What is Nmap used for?','// Nmap — Network Scanner','bash','["Mencoba banyak kombinasi username/password untuk membobol halaman login.","Pemindai otomatis celah keamanan aplikasi web open-source dari OWASP.","Mengirim request HTTP langsung dari terminal untuk menguji API atau endpoint secara manual.","Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya."]'::jsonb,'["Tries many username/password combinations to break into a login page.","OWASP''s open-source automated web application vulnerability scanner.","Sends HTTP requests directly from the terminal to manually test an API or endpoint.","Scans hosts and open ports on a network, including service versions."]'::jsonb,3,'Nmap: Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya.','Nmap: Scans hosts and open ports on a network, including service versions.','Nmap adalah kategori "Network Scanner".','Nmap falls under the "Network Scanner" category.','Jalankan di terminal diarahkan ke IP/domain target; hasilnya daftar port terbuka dan servis yang berjalan.','Run it in a terminal pointed at the target IP/domain; the output lists open ports and running services.','Admin server yang baik menutup port yang tidak dipakai (least privilege) alih-alih mengandalkan ''tidak ketahuan''.','A good admin closes unused ports (least privilege) instead of relying on ''security through obscurity''.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] -i eth0 -f "port 80"','bash','["Wireshark","Gobuster","Nmap","Burp Suite"]'::jsonb,'["Wireshark","Gobuster","Nmap","Burp Suite"]'::jsonb,0,'Wireshark (Packet Analyzer): Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.','Wireshark (Packet Analyzer): Captures and inspects network packets in fine detail.','Tools ini bernama Wireshark, fungsinya: Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.','This tool is called Wireshark, and it: Captures and inspects network packets in fine detail.','Pilih antarmuka jaringan, klik Start, lalu filter paket dengan ekspresi seperti http.request.','Select a network interface, click Start, then filter packets with an expression like http.request.','Data sensitif yang lewat tanpa HTTPS bisa terbaca jelas lewat tool ini — itulah kenapa TLS wajib, bukan opsional.','Sensitive data sent without HTTPS is plainly readable with this tool — that''s why TLS is mandatory, not optional.'),
('demi_god','fill','Lengkapi perintah Wireshark berikut:','Complete the following Wireshark command:','wireshark -i eth0 ____ "port 80"','bash','["-x","-z","-q","-f"]'::jsonb,'["-x","-z","-q","-f"]'::jsonb,3,'Bagian yang hilang adalah "-f". Pilih antarmuka jaringan, klik Start, lalu filter paket dengan ekspresi seperti http.request.','The missing part is "-f". Select a network interface, click Start, then filter packets with an expression like http.request.','Wireshark dipakai untuk: Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.','Wireshark is used to: Captures and inspects network packets in fine detail.','Pilih antarmuka jaringan, klik Start, lalu filter paket dengan ekspresi seperti http.request.','Select a network interface, click Start, then filter packets with an expression like http.request.','Data sensitif yang lewat tanpa HTTPS bisa terbaca jelas lewat tool ini — itulah kenapa TLS wajib, bukan opsional.','Sensitive data sent without HTTPS is plainly readable with this tool — that''s why TLS is mandatory, not optional.'),
('demi_god','guess','Apa fungsi dari Wireshark?','What is Wireshark used for?','// Wireshark — Packet Analyzer','bash','["Memecahkan hash password lewat serangan kamus atau brute-force offline.","Memeriksa dan mengubah HTML/CSS/JS serta request jaringan langsung dari browser.","Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.","Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya."]'::jsonb,'["Cracks password hashes via dictionary or offline brute-force attacks.","Inspects and edits HTML/CSS/JS and network requests right from the browser.","Captures and inspects network packets in fine detail.","Scans hosts and open ports on a network, including service versions."]'::jsonb,2,'Wireshark: Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.','Wireshark: Captures and inspects network packets in fine detail.','Wireshark adalah kategori "Packet Analyzer".','Wireshark falls under the "Packet Analyzer" category.','Pilih antarmuka jaringan, klik Start, lalu filter paket dengan ekspresi seperti http.request.','Select a network interface, click Start, then filter packets with an expression like http.request.','Data sensitif yang lewat tanpa HTTPS bisa terbaca jelas lewat tool ini — itulah kenapa TLS wajib, bukan opsional.','Sensitive data sent without HTTPS is plainly readable with this tool — that''s why TLS is mandatory, not optional.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] -h https://target.id -ssl','bash','["Nikto","WPScan","Gobuster","Wireshark"]'::jsonb,'["Nikto","WPScan","Gobuster","Wireshark"]'::jsonb,0,'Nikto (Web Server Scanner): Memindai server web untuk file berbahaya, konfigurasi usang, dan masalah keamanan umum.','Nikto (Web Server Scanner): Scans a web server for dangerous files, outdated configs, and common security issues.','Tools ini bernama Nikto, fungsinya: Memindai server web untuk file berbahaya, konfigurasi usang, dan masalah keamanan umum.','This tool is called Nikto, and it: Scans a web server for dangerous files, outdated configs, and common security issues.','Arahkan ke host target; hasilnya daftar temuan seperti header hilang atau direktori sensitif terbuka.','Point it at the target host; the output lists findings like missing headers or exposed sensitive directories.','Header keamanan (X-Frame-Options, CSP, dll.) murah untuk dipasang tapi sering terlewat di aplikasi nyata.','Security headers (X-Frame-Options, CSP, etc.) are cheap to add but often forgotten in real apps.'),
('demi_god','fill','Lengkapi perintah Nikto berikut:','Complete the following Nikto command:','nikto -h https://target.id ____','bash','["-evasion","-ssl","-raw","-update"]'::jsonb,'["-evasion","-ssl","-raw","-update"]'::jsonb,1,'Bagian yang hilang adalah "-ssl". Arahkan ke host target; hasilnya daftar temuan seperti header hilang atau direktori sensitif terbuka.','The missing part is "-ssl". Point it at the target host; the output lists findings like missing headers or exposed sensitive directories.','Nikto dipakai untuk: Memindai server web untuk file berbahaya, konfigurasi usang, dan masalah keamanan umum.','Nikto is used to: Scans a web server for dangerous files, outdated configs, and common security issues.','Arahkan ke host target; hasilnya daftar temuan seperti header hilang atau direktori sensitif terbuka.','Point it at the target host; the output lists findings like missing headers or exposed sensitive directories.','Header keamanan (X-Frame-Options, CSP, dll.) murah untuk dipasang tapi sering terlewat di aplikasi nyata.','Security headers (X-Frame-Options, CSP, etc.) are cheap to add but often forgotten in real apps.'),
('demi_god','guess','Apa fungsi dari Nikto?','What is Nikto used for?','// Nikto — Web Server Scanner','bash','["Mendeteksi dan mengeksploitasi celah SQL injection pada parameter aplikasi web secara otomatis.","Memeriksa dan mengubah HTML/CSS/JS serta request jaringan langsung dari browser.","Mencoba banyak kombinasi username/password untuk membobol halaman login.","Memindai server web untuk file berbahaya, konfigurasi usang, dan masalah keamanan umum."]'::jsonb,'["Automatically detects and exploits SQL injection flaws in web app parameters.","Inspects and edits HTML/CSS/JS and network requests right from the browser.","Tries many username/password combinations to break into a login page.","Scans a web server for dangerous files, outdated configs, and common security issues."]'::jsonb,3,'Nikto: Memindai server web untuk file berbahaya, konfigurasi usang, dan masalah keamanan umum.','Nikto: Scans a web server for dangerous files, outdated configs, and common security issues.','Nikto adalah kategori "Web Server Scanner".','Nikto falls under the "Web Server Scanner" category.','Arahkan ke host target; hasilnya daftar temuan seperti header hilang atau direktori sensitif terbuka.','Point it at the target host; the output lists findings like missing headers or exposed sensitive directories.','Header keamanan (X-Frame-Options, CSP, dll.) murah untuk dipasang tapi sering terlewat di aplikasi nyata.','Security headers (X-Frame-Options, CSP, etc.) are cheap to add but often forgotten in real apps.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] -u "https://target.id/produk?id=1" --dbs','bash','["Nikto","HTTPie","John the Ripper","SQLmap"]'::jsonb,'["Nikto","HTTPie","John the Ripper","SQLmap"]'::jsonb,3,'SQLmap (SQL Injection Tool): Mendeteksi dan mengeksploitasi celah SQL injection pada parameter aplikasi web secara otomatis.','SQLmap (SQL Injection Tool): Automatically detects and exploits SQL injection flaws in web app parameters.','Tools ini bernama SQLmap, fungsinya: Mendeteksi dan mengeksploitasi celah SQL injection pada parameter aplikasi web secara otomatis.','This tool is called SQLmap, and it: Automatically detects and exploits SQL injection flaws in web app parameters.','Beri URL yang punya parameter dicurigai; tool mencoba berbagai payload untuk membuktikan celahnya.','Give it a URL with a suspected parameter; it tries various payloads to prove the vulnerability.','Prepared statements / parameterized query menutup celah ini total — jangan pernah menyambung string SQL mentah.','Prepared/parameterized statements close this gap entirely — never concatenate raw SQL strings.'),
('demi_god','fill','Lengkapi perintah SQLmap berikut:','Complete the following SQLmap command:','sqlmap -u "https://target.id/produk?id=1" ____','bash','["--dbs","--os-shell","--tamper","--forms"]'::jsonb,'["--dbs","--os-shell","--tamper","--forms"]'::jsonb,0,'Bagian yang hilang adalah "--dbs". Beri URL yang punya parameter dicurigai; tool mencoba berbagai payload untuk membuktikan celahnya.','The missing part is "--dbs". Give it a URL with a suspected parameter; it tries various payloads to prove the vulnerability.','SQLmap dipakai untuk: Mendeteksi dan mengeksploitasi celah SQL injection pada parameter aplikasi web secara otomatis.','SQLmap is used to: Automatically detects and exploits SQL injection flaws in web app parameters.','Beri URL yang punya parameter dicurigai; tool mencoba berbagai payload untuk membuktikan celahnya.','Give it a URL with a suspected parameter; it tries various payloads to prove the vulnerability.','Prepared statements / parameterized query menutup celah ini total — jangan pernah menyambung string SQL mentah.','Prepared/parameterized statements close this gap entirely — never concatenate raw SQL strings.'),
('demi_god','guess','Apa fungsi dari SQLmap?','What is SQLmap used for?','// SQLmap — SQL Injection Tool','bash','["Menebak nama direktori/file tersembunyi di server web dengan daftar kata (wordlist).","Memindai host dan port yang terbuka di sebuah jaringan, termasuk versi servisnya.","Mendeteksi dan mengeksploitasi celah SQL injection pada parameter aplikasi web secara otomatis.","Memecahkan hash password lewat serangan kamus atau brute-force offline."]'::jsonb,'["Brute-forces hidden directory/file names on a web server using a wordlist.","Scans hosts and open ports on a network, including service versions.","Automatically detects and exploits SQL injection flaws in web app parameters.","Cracks password hashes via dictionary or offline brute-force attacks."]'::jsonb,2,'SQLmap: Mendeteksi dan mengeksploitasi celah SQL injection pada parameter aplikasi web secara otomatis.','SQLmap: Automatically detects and exploits SQL injection flaws in web app parameters.','SQLmap adalah kategori "SQL Injection Tool".','SQLmap falls under the "SQL Injection Tool" category.','Beri URL yang punya parameter dicurigai; tool mencoba berbagai payload untuk membuktikan celahnya.','Give it a URL with a suspected parameter; it tries various payloads to prove the vulnerability.','Prepared statements / parameterized query menutup celah ini total — jangan pernah menyambung string SQL mentah.','Prepared/parameterized statements close this gap entirely — never concatenate raw SQL strings.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] dir -u https://target.id -w wordlist.txt','bash','["Burp Suite","Gobuster","OWASP ZAP","WPScan"]'::jsonb,'["Burp Suite","Gobuster","OWASP ZAP","WPScan"]'::jsonb,1,'Gobuster (Directory Brute-forcer): Menebak nama direktori/file tersembunyi di server web dengan daftar kata (wordlist).','Gobuster (Directory Brute-forcer): Brute-forces hidden directory/file names on a web server using a wordlist.','Tools ini bernama Gobuster, fungsinya: Menebak nama direktori/file tersembunyi di server web dengan daftar kata (wordlist).','This tool is called Gobuster, and it: Brute-forces hidden directory/file names on a web server using a wordlist.','Beri URL target dan wordlist; tool mencoba tiap kata sebagai path dan melaporkan yang merespons.','Give it a target URL and a wordlist; it tries each word as a path and reports which ones respond.','File backup (.bak, .old) atau folder admin yang ''disembunyikan'' tetap bisa ditemukan — jangan andalkan itu sebagai proteksi.','''Hidden'' backup files (.bak, .old) or admin folders can still be found — never rely on that as protection.'),
('demi_god','fill','Lengkapi perintah Gobuster berikut:','Complete the following Gobuster command:','gobuster ____ -u https://target.id -w wordlist.txt','bash','["dir","s3","dns","vhost"]'::jsonb,'["dir","s3","dns","vhost"]'::jsonb,0,'Bagian yang hilang adalah "dir". Beri URL target dan wordlist; tool mencoba tiap kata sebagai path dan melaporkan yang merespons.','The missing part is "dir". Give it a target URL and a wordlist; it tries each word as a path and reports which ones respond.','Gobuster dipakai untuk: Menebak nama direktori/file tersembunyi di server web dengan daftar kata (wordlist).','Gobuster is used to: Brute-forces hidden directory/file names on a web server using a wordlist.','Beri URL target dan wordlist; tool mencoba tiap kata sebagai path dan melaporkan yang merespons.','Give it a target URL and a wordlist; it tries each word as a path and reports which ones respond.','File backup (.bak, .old) atau folder admin yang ''disembunyikan'' tetap bisa ditemukan — jangan andalkan itu sebagai proteksi.','''Hidden'' backup files (.bak, .old) or admin folders can still be found — never rely on that as protection.'),
('demi_god','guess','Apa fungsi dari Gobuster?','What is Gobuster used for?','// Gobuster — Directory Brute-forcer','bash','["Mencoba banyak kombinasi username/password untuk membobol halaman login.","Menangkap dan menganalisis paket data yang lalu-lalang di jaringan secara mendetail.","Menangkap dan memanipulasi request/response HTTP antara browser dan server sebelum terkirim.","Menebak nama direktori/file tersembunyi di server web dengan daftar kata (wordlist)."]'::jsonb,'["Tries many username/password combinations to break into a login page.","Captures and inspects network packets in fine detail.","Intercepts and manipulates HTTP requests/responses between browser and server before they''re sent.","Brute-forces hidden directory/file names on a web server using a wordlist."]'::jsonb,3,'Gobuster: Menebak nama direktori/file tersembunyi di server web dengan daftar kata (wordlist).','Gobuster: Brute-forces hidden directory/file names on a web server using a wordlist.','Gobuster adalah kategori "Directory Brute-forcer".','Gobuster falls under the "Directory Brute-forcer" category.','Beri URL target dan wordlist; tool mencoba tiap kata sebagai path dan melaporkan yang merespons.','Give it a target URL and a wordlist; it tries each word as a path and reports which ones respond.','File backup (.bak, .old) atau folder admin yang ''disembunyikan'' tetap bisa ditemukan — jangan andalkan itu sebagai proteksi.','''Hidden'' backup files (.bak, .old) or admin folders can still be found — never rely on that as protection.'),
('demi_god','guess','Tools apa yang dipakai di sini?','Which tool is being used here?','[TOOL] -l admin -P rockyou.txt ssh://192.168.1.10','bash','["Gobuster","Hydra","SQLmap","curl"]'::jsonb,'["Gobuster","Hydra","SQLmap","curl"]'::jsonb,1,'Hydra (Login Brute-forcer): Mencoba banyak kombinasi username/password untuk membobol halaman login.','Hydra (Login Brute-forcer): Tries many username/password combinations to break into a login page.','Tools ini bernama Hydra, fungsinya: Mencoba banyak kombinasi username/password untuk membobol halaman login.','This tool is called Hydra, and it: Tries many username/password combinations to break into a login page.','Beri daftar user, daftar password, dan target servis (ssh, http-post-form, dll).','Give it a user list, a password list, and the target service (ssh, http-post-form, etc.).','Rate limiting dan penguncian akun setelah beberapa percobaan gagal adalah pertahanan utama melawan ini.','Rate limiting and account lockout after a few failed attempts are the main defenses against this.'),
